USE aegis;

-- QUERY 1: Create companion session. Its called when user selects a companion and taps Start Journey
-- Status starts as PENDING — waiting for companion to join. The session_code is a random 6 char code generated by Spring Boot which calls this once per selected companion.
INSERT INTO companion_sessions
(session_id, user_id, companion_id, route_id, session_code)
VALUES (UUID(), ?, ?, ?, ?);

-- QUERY 2: Companion joins using session code. Its called when companion enters 6 char code in the app
-- Only updates if status is PENDING — prevents rejoining ended sessions
UPDATE companion_sessions
SET status = 'ACTIVE'
WHERE session_code = ?
AND status = 'PENDING';

-- QUERY 3: Get session by session code. Its called when companion enters code to verify it exists.
-- Returns session details before allowing WebSocket subscription.
SELECT session_id, user_id, companion_id, route_id, status, started_at
FROM companion_sessions
WHERE session_code = ?;

-- QUERY 4: Get active and pending sessions for user. Its called to show user who is currently watching their journey.
-- Returns both PENDING (not yet joined) and ACTIVE (joined) sessions.
SELECT cs.session_id, u.full_name AS companion_name,
       cs.status, cs.started_at, cs.session_code
FROM companion_sessions cs
JOIN users u ON cs.companion_id = u.user_id
WHERE cs.user_id = ?
AND cs.status IN ('PENDING', 'ACTIVE');

-- QUERY 5: End session on arrival. Its called when user arrives at destination.
-- Only ends ACTIVE sessions — PENDING sessions also ended so companions who never joined are cleaned up too.
UPDATE companion_sessions
SET status = 'ENDED',
    ended_at = CURRENT_TIMESTAMP
WHERE user_id = ?
AND route_id = ?
AND status IN ('PENDING', 'ACTIVE');

-- QUERY 6: Get session by session_id. Its called by WebSocket server to verify session before connection
-- Only returns ACTIVE sessions — PENDING not yet ready for WebSocket
SELECT session_id, user_id, companion_id, route_id, status
FROM companion_sessions
WHERE session_id = ?
AND status = 'ACTIVE';

-- QUERY 7: Check inactive sessions for alert. Its called by Spring Boot scheduled task every minute.
-- Returns ACTIVE sessions with no location update in 5 minutes. Then the companion gets notification pushes by Spring Boot.
SELECT cs.session_id, cs.companion_id
FROM companion_sessions cs
WHERE cs.status = 'ACTIVE'
AND NOT EXISTS (
    SELECT 1 FROM location_updates lu
    WHERE lu.session_id = cs.session_id
    AND lu.recorded_at > DATE_SUB(NOW(), INTERVAL 5 MINUTE)
);